            Inline.IlAnalyze(d.Fw, s.Lt, d.Et, d.Gl, d.Ift, s.Sf, d.An, d.Txt, d.Pg, m.Pages, np, m.Text, s.Hc, s.Isw);
        }
        Para.PaBuild(d.Fw, d.Et, np, m.Pages, m.Layout, m.Nodes, m.Attrs, m.Regions, m.Text, s.Ord, s.Raw, s.Tmp, s.Fr, s.Gp, s.Lt, s.Ls, s.Sd, s.It, s.Io, s.Rw, s.Gu, s.Ac, s.Tm, s.Cf, s.Lo, s.Pr, s.Dbg, s.Hc, s.Tb, s.Tc, s.Tw, s.Tq, m.Ledger, s.Ii, s.Al);
        if (kind == 0) {
            EnFigures(m, s, d, c.Level);
        }
        Restruct.RsRun(m.Nodes, m.Attrs, m.Regions, m.Text, s.Rn, s.Ra, s.Rr, s.Rnm, s.Rstk, s.Rused, s.Rout, m.Layout);
        emon.Port.CellsSwap(m.Nodes, s.Rn);
        emon.Port.CellsSwap(m.Attrs, s.Ra);
        emon.Port.CellsSwap(m.Regions, s.Rr);
        Furniture.FuWrite(s.Fo, s.Fp, s.Ft, s.Pl, np, m.Nodes, m.Attrs, m.Regions, m.Text, m.Pages, m.Ledger, s.Tmp);
        if (kind == 0) {
            Tlhealth.ThWrite(d.Fa, d.Wd, d.Et, m.Ledger, m.Text, s.Tmp, s.Ttx);
            Gfuse.GfWrite(s.Gfa, m.Ledger);
        }
        Scan.ScTag(m.Nodes, m.Attrs, m.Text, m.Regions, m.Pages, d.Mask, c.Ocr);
        Rasterplan.RpSettings(m.Nodes, m.Attrs, m.Text, c.Scope);
        if (d.Fused == 1) {
            Arbiter.ArWrite(s.Afa, ev.Owords, d.Et, m.Ledger, m.Text, s.Tmp, s.Ttx);
            Arbiter.ArTag(m.Nodes, m.Regions, d.Fw, s.Fv);
            w = Sealmark.SmWrite(s.Sm, d.Et, m.Nodes, m.Attrs, m.Regions, m.Text, s.Sn, s.Sa, s.Sr, s.Snm);
            if (w > 0) {
                emon.Port.CellsSwap(m.Nodes, s.Sn);
                emon.Port.CellsSwap(m.Attrs, s.Sa);
                emon.Port.CellsSwap(m.Regions, s.Sr);
            }
        }
        if (kind == 0) {
            EnFields(m, s, d);
        }
        if (c.Haveloc != 0) {
            w = emon.Port.CellsLen(m.Text);
            int i = 0;
            while (i < emon.Port.CellsLen(c.Lcl)) {
                Model.TextAppendCp(m.Text, emon.Port.CellsAt(c.Lcl, i));
                i += 1;
            }
            Model.NodeSetAttrText(m.Nodes, m.Attrs, 0, Model.FkLocale(), w, emon.Port.CellsLen(m.Text) - w);
        }
        if (kind == 0) {
            if (c.Level == 2) {
                pending = 1;
            }
            if ((c.Level != 0) && (pending == 0)) {
                EnAssetStage(c, m, s, d.Cand, d.Cbytes);
            }
        } else if (c.Level != 0) {
            Asset.AsPageCands(m.Pages, d.Cand);
            if (c.Level == 2) {
                pending = 1;
            } else {
                EnAssetStage(c, m, s, d.Cand, d.Cbytes);
            }
        }
        if (pending == 0) {
            w = EnSeal(m, s.Chk, s.Sealout, c.Level);
            if (w != 0) {
                d.Fcode = emon.Port.CellsAt(s.Sealout, 0);
                d.Fnode = emon.Port.CellsAt(s.Sealout, 1);
                return w + 2;
            }
        }
        return pending;
    }
    public static int EnFinishRaster(emon.Enctx.Cfg c, emon.Enctx.Doc d, emon.Enctx.EvArenas ev, emon.Enctx.Arenas m, emon.Enctx.Scratch s) {
        // The raster document unit: stage 3 over the frames' OCR lines. `m` is the Model the document pass began (its pages and nodes); an image has no text layer, so
        // the glyph arenas are empty and nothing is set aside.
        int np = Model.PageCount(m.Pages);
        if (c.Keep != 0) {
            EnDump(d.Et, d.Gl, d.Wd, d.Ln, d.Mk, d.Fnt, d.Grl, d.Gfl, s.Ggp, s.Grg, ev, d.Evidence);
        }
        Tlhealth.ThAppend(d.Wd, d.Ln, d.Fw, d.Fl, 0);
        return EnStage3(c, d, ev, m, s, np, 1);
    }
    public static int EnFinishPdf(emon.Enctx.Cfg c, emon.Enctx.Doc d, emon.Enctx.EvArenas ev, emon.Enctx.Arenas m, emon.Enctx.Scratch s) {
        // The PDF document unit (stage 3) over the text layer and whatever the page units added to it: fusion's arbitration, the evidence, then stage 3.
        int np = Pdfdoc.PdPgCount(d.Pg);
        int pcode = 0;
        Tlhealth.ThAppend(d.Wd, d.Ln, d.Fw, d.Fl, d.Nl0);
        if (emon.Port.CellsLen(d.Cg) > 0) {
            d.Fused = 1;
        }
        if (Sigmark.SgHasDigital(d.An) == 1) {
            d.Fused = 1;
        }
        if ((c.Ocr != 0) && (d.Fused == 0) && (emon.Port.CellsLen(ev.Owords) == 0)) {
            emon.Port.CellsFree(ev.Epages);
            emon.Port.CellsFree(ev.Feats);
        }
        Gfuse.GfFuse(np, ev.Epages, ev.Inks, ev.Rules, ev.Prims, ev.Oblocks, ev.Owords, d.Wd, d.Et, d.Pa, d.Im, ev.Feats, d.Grl, d.Gfl, s.Ggp, s.Grg, ev.Refs, d.Hl, s.Fx, s.Gfa, s.Ga0, s.Ga1, s.Ga2, s.Ga3, s.Ga4, s.Ga5, s.Ga6);
        if (d.Fused == 1) {
            Health.HlDoc(ev.Feats, d.Fw, d.Hl);
            int trust0 = Pdfstruct.TgTrust(d.Ss);
            Sealmark.SmFind(d.Pa, d.Pts, d.Gl, d.Fw, d.Et, ev.Epages, d.Cg, ev.Refs, ev.Owords, d.An, d.Txt, np, s.Sm, s.Sscr, s.Stmp, s.Sgc);
            Arbiter.ArDoc(d.Cg, ev.Refs, d.Fw, d.Fl, d.Et, ev.Feats, ev.Owords, ev.Olines, ev.Oruns, ev.Osyms, ev.Images, ev.Epages, d.Gl, d.Mk, d.An, d.Txt, trust0, s.Rc, s.Nfw, s.Nfl, s.Fv, s.Fx, s.Afa, s.Gd, s.Gv, s.W2g, s.O2g, s.Pp, s.Ftw, s.Ftl, d.Xs0);
            emon.Port.CellsSwap(d.Fw, s.Nfw);
            emon.Port.CellsSwap(d.Fl, s.Nfl);
            pcode = Player.PlCheck(d.Cg, d.Fw, d.Fl, s.Fv, d.Fa, s.Fx, d.Hl, d.Grl, s.Sm, d.Gfl, s.Ggp, s.Grg, d.Et, ev.Refs, d.Gl);
            if (pcode != 0) {
                d.Fcode = pcode;
                return 2;
            }
        }
        if (c.Keep != 0) {
            if (d.Hassnap == 0) {
                emon.Port.CellsCopyInto(d.Snapg, d.Gl);
                emon.Port.CellsCopyInto(d.Snapk, d.Mk);
                emon.Port.CellsCopyInto(d.Snapf, d.Fnt);
            }
            if (d.Fused == 1) {
                emon.Port.CellsCopyInto(s.Fad, d.Fa);
                int i = 0;
                while (i < emon.Port.CellsLen(s.Afa)) {
                    emon.Port.CellsPush(s.Fad, emon.Port.CellsAt(s.Afa, i));
                    i += 1;
                }
                Player.PlEmitOpen(d.Evidence, 0, ev.Epages, ev.Views, ev.Pts, ev.Refs, d.Et, ev.Feats, d.Snapg, d.Wd, d.Ln, d.Snapk, d.Snapf, ev.Paths, ev.Images, ev.Oruns, ev.Oblocks, ev.Olines, ev.Owords, ev.Osyms, ev.Oalts, ev.Inks, ev.Comps, ev.Rules, ev.Prims, ev.Tlines, d.Cg, d.Fw, d.Fl, s.Fv, s.Fad, s.Fx, d.Hl, d.Grl, s.Sm, d.Gfl, s.Ggp, s.Grg);
            } else {
                EnDump(d.Et, d.Snapg, d.Wd, d.Ln, d.Snapk, d.Snapf, d.Grl, d.Gfl, s.Ggp, s.Grg, ev, d.Evidence);
            }
        }
        Model.ModelInit(m.Nodes, m.Attrs, m.Regions, m.Text, m.Pages, m.Ledger, m.Layout);
        Para.PaPages(d.Pg, m.Pages);
        return EnStage3(c, d, ev, m, s, np, 0);
    }
    public static int EnFinish(emon.Enctx.Cfg c, emon.Enctx.Doc d, emon.Enctx.EvArenas ev, emon.Enctx.Arenas m, emon.Enctx.Scratch s) {
        // The document unit of whatever kind the document pass made (`kind`): `en-finish-pdf` or `en-finish-raster`. Answers as the file's head says.
        if (d.Kind == EnKindPdf()) {
            return EnFinishPdf(c, d, ev, m, s);
        }
        return EnFinishRaster(c, d, ev, m, s);
    }
}
